// DecodeOptionsRequest returns a decoder for requests sent to the dictionaries
// options endpoint.
func DecodeOptionsRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*dictionaries.OptionsPayload, error) {
	return func(r *http.Request) (*dictionaries.OptionsPayload, error) {
		var payload *dictionaries.OptionsPayload
		var (
			code     string
			language string
			ids      []int64
			search   string
			cookie   string
			err      error

			params = mux.Vars(r)
		)
		code = params["code"]
		if utf8.RuneCountInString(code) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("code", code, utf8.RuneCountInString(code), 1, true))
		}
		if utf8.RuneCountInString(code) > 80 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("code", code, utf8.RuneCountInString(code), 80, false))
		}
		qp := r.URL.Query()
		languageRaw := qp.Get("language")
		if languageRaw != "" {
			language = languageRaw
		} else {
			language = "en"
		}
		if !(language == "en" || language == "zh-CN") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("language", language, []any{"en", "zh-CN"}))
		}
		{
			idsRaw := qp["ids"]
			if idsRaw != nil {
				ids = make([]int64, len(idsRaw))
				for i, rv := range idsRaw {
					v, err2 := strconv.ParseInt(rv, 10, 64)
					if err2 != nil {
						err = goa.MergeErrors(err, goa.InvalidFieldTypeError("ids", idsRaw, "array of integers"))
					}
					ids[i] = v
				}
			}
		}
		if len(ids) > 200 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("ids", ids, len(ids), 200, false))
		}
		searchRaw := qp.Get("search")
		if searchRaw != "" {
			search = searchRaw
		}
		if utf8.RuneCountInString(search) > 100 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("search", search, utf8.RuneCountInString(search), 100, false))
		}
		cookie = r.Header.Get("Cookie")
		if cookie == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("cookie", "header"))
		}
		if err != nil {
			return payload, err
		}
		payload = NewOptionsPayload(code, language, ids, search, cookie)
		if index := strings.IndexByte(string(payload.Cookie), ' '); index >= 0 {
			// Remove authorization scheme prefix (e.g. "Bearer")
			payload.Cookie = payload.Cookie[index+1:]
		}

		return payload, nil
	}
}

